fn solve(input: Vec<char>) -> Vec<char> {
    // We know input has length exactly 3 and each char is 'A' or 'B'.
    // Check if there is at least one adjacent pair that differs.
    for i in 0..2 {
        if input[i] != input[i + 1] {
            return "Yes".chars().collect();
        }
    }
    "No".chars().collect()
}

