    assert_eq!(solve(input1), "No".chars().collect::<Vec<char>>());
    assert_eq!(solve(input2), "Yes".chars().collect::<Vec<char>>());
    assert_eq!(solve(input3), "Yes".chars().collect::<Vec<char>>());

